package com.mps.attendance;
import com.mps.attendance.dto.AttendanceDtos.*; import com.mps.attendance.service.AttendanceService; import com.mps.auth.security.UserPrincipal; import com.mps.common.ApiResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/attendance") public class AttendanceController { private final AttendanceService service; public AttendanceController(AttendanceService s){service=s;}
 @GetMapping("/schedule/{scheduleId}") @PreAuthorize("hasAuthority('attendance.read')") public ApiResponse<RegisterView> get(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID scheduleId){return ApiResponse.ok("Attendance register loaded.",service.getOrCreate(p,scheduleId));}
 @PutMapping("/schedule/{scheduleId}") @PreAuthorize("hasAuthority('attendance.manage')") public ApiResponse<RegisterView> save(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID scheduleId,@Valid @RequestBody SaveRegisterRequest req){return ApiResponse.ok("Attendance saved.",service.save(p,scheduleId,req));}
 @PostMapping("/schedule/{scheduleId}/finalize") @PreAuthorize("hasAuthority('attendance.finalize')") public ApiResponse<RegisterView> finalizeRegister(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID scheduleId){return ApiResponse.ok("Attendance finalized.",service.finalizeRegister(p,scheduleId));}
 @PostMapping("/schedule/{scheduleId}/members/{memberId}/correct") @PreAuthorize("hasAuthority('attendance.correct')") public ApiResponse<RegisterView> correct(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID scheduleId,@PathVariable UUID memberId,@Valid @RequestBody CorrectionRequest req){return ApiResponse.ok("Attendance corrected.",service.correct(p,scheduleId,memberId,req));}
}
